32	#define gk104_volt(p) container_of((p), struct gk104_volt, base)
33	struct gk104_volt {
34		struct nvkm_volt base;
35		struct nvbios_volt bios;
36	};
37	
38	static int
39	gk104_volt_get(struct nvkm_volt *base)
40	{
41		struct nvbios_volt *bios = &gk104_volt(base)->bios;
42		struct nvkm_device *device = base->subdev.device;
43		u32 div, duty;
44	
45		div  = nvkm_rd32(device, 0x20340);
46		duty = nvkm_rd32(device, 0x20344);
47	
48		return bios->base + bios->pwm_range * duty / div;
49	}
